/* DSX plugin: dsh-whale-widget v0.3.0 (port) */
/* upstream: https://github.com/MeteorNOX/DeepSeek-Balance-Whale-Widget */
/* upstream license: MIT, Copyright (c) 2026 MeteorNOX (see upstream LICENSE) */
/* local changes: DSX runtime shim, forced chat-root gate, label tweaks; no upstream code removed */
/* host: DeepSeek Agent (DSX runtime); shim serves /dsh-whale/* */
/* build: vendor/build-whale-dsh.js */
module.exports = {
  onLoad: function (ctx, meta) {
    var W = window;
    var ASSETS = {
      'image.png': { mime: 'image/png', b64: '' },
      'rua.gif': { mime: 'image/gif', b64: '' },
      'Ya1.mp3': { mime: 'audio/mpeg', b64: '' },
      'Ya2.mp3': { mime: 'audio/mpeg', b64: '' },
      'task-end-a.wav': { mime: 'audio/wav', b64: '' },
      'minecraft-exp-orb.wav': { mime: 'audio/wav', b64: '' },
    };
    var SRC_B64 = '';

    function b64ToBytes(b64) {
      var bin = atob(b64), n = bin.length, out = new Uint8Array(n);
      for (var i = 0; i < n; i++) out[i] = bin.charCodeAt(i);
      return out;
    }
    function assetDataUrl(name) {
      var a = ASSETS[name];
      return a ? ('data:' + a.mime + ';base64,' + a.b64) : null;
    }
    function splitPath(u, pfx) {
      var i = u.indexOf(pfx);
      if (i < 0) return null;
      var rel = u.slice(i + pfx.length), q = '';
      var qi = rel.indexOf('?');
      if (qi >= 0) { q = rel.slice(qi + 1); rel = rel.slice(0, qi); }
      return { path: rel, query: q };
    }
    function assetNameFromPath(p) {
      if (p === 'image.png') return 'image.png';
      if (p === 'role-image.png') return 'image.png';
      if (p === 'rua.gif') return 'rua.gif';
      if (p === 'audio-fragment.wav') return 'task-end-a.wav';
      if (p === 'sound/press.mp3') return 'Ya1.mp3';
      if (p === 'sound/release.mp3') return 'Ya2.mp3';
      return null;
    }
    function jsonResp(o, s) {
      return Promise.resolve(new Response(JSON.stringify(o), {
        status: s || 200,
        headers: { 'Content-Type': 'application/json' }
      }));
    }
    function tmData() {
      try {
        var T = W.__TM;
        if (T && typeof T.whale === 'function') return T.whale();
      } catch (e) {}
      return null;
    }
    function num(v, d) { var n = Number(v); return isFinite(n) ? n : d; }
    function handleRoute(p) {
      var an = assetNameFromPath(p);
      if (an && ASSETS[an]) {
        var a = ASSETS[an];
        return Promise.resolve(new Response(b64ToBytes(a.b64), {
          status: 200,
          headers: { 'Content-Type': a.mime }
        }));
      }
      if (p === 'balance.json') {
        var w = tmData();
        var saved = w ? num(w.hi, 0) : 0;
        return jsonResp({
          ok: true,
          totalBalance: saved,
          currency: 'CNY',
          todayUsage: saved,
          isPeak: false
        });
      }
      if (p === 'size.json')            return jsonResp({ ok: true, scale: 1.5 });
      if (p === 'last-turn.json') {
        var w2 = tmData();
        if (!w2 || !w2.seq) return jsonResp({ ok: false });
        return jsonResp({
          ok: true,
          seq: w2.seq,
          turn: w2.turns,
          amount: num(w2.lastTurnHi, 0)
        });
      }
      if (p === 'usage-records.json')   return jsonResp({ ok: true, records: [] });
      if (p === 'usage-settings.json')  return jsonResp({ ok: true });
      if (p === 'api-models.json')      return jsonResp({ ok: true, models: [] });
      if (p === 'roles.json')           return jsonResp({ ok: true, roles: [] });
      if (p === 'bubble-imgs.json')     return jsonResp({ ok: true, imgs: [] });
      if (p === 'audio.json')           return jsonResp({ ok: true, sets: [] });
      if (p === 'bubble.json')          return jsonResp({ ok: true });
      return jsonResp({ ok: false, error: 'not implemented: ' + p });
    }

    var _fetch = W.fetch;
    var _hook = function (input, init) {
      var url = '';
      try { url = (typeof input === 'string') ? input : ((input && input.url) || String(input)); } catch (e) {}
      var r = splitPath(url, '/dsh-whale/');
      if (r) return handleRoute(r.path);
      return _fetch.apply(this, arguments);
    };
    _hook.__dsxWhaleMock = true;
    _hook.__dsxWhaleOriginal = _fetch;
    W.fetch = _hook;

    var _imgDesc = Object.getOwnPropertyDescriptor(HTMLImageElement.prototype, 'src');
    if (_imgDesc && _imgDesc.set) {
      Object.defineProperty(HTMLImageElement.prototype, 'src', {
        configurable: true,
        enumerable: _imgDesc.enumerable,
        get: _imgDesc.get,
        set: function (v) {
          try {
            if (typeof v === 'string') {
              var r = splitPath(v, '/dsh-whale/');
              if (r) {
                var an = assetNameFromPath(r.path);
                var du = an && assetDataUrl(an);
                if (du) v = du;
              }
            }
          } catch (e) {}
          return _imgDesc.set.call(this, v);
        }
      });
    }

    var _Audio = W.Audio;
    function _AudioHook(src) {
      try {
        if (typeof src === 'string') {
          var r = splitPath(src, '/dsh-whale/');
          if (r) {
            var an = assetNameFromPath(r.path);
            var du = an && assetDataUrl(an);
            if (du) src = du;
          }
        }
      } catch (e) {}
      return new _Audio(src);
    }
    _AudioHook.prototype = _Audio.prototype;
    W.Audio = _AudioHook;

    try {
      var SRC = new TextDecoder().decode(b64ToBytes(SRC_B64));
      (new Function(SRC))();
      ctx.log('[whale-dsh] widget activated');
    } catch (e) {
      ctx.error('[whale-dsh] run failed: ' + (e && e.message));
    }

    this._cleanup = function () {
      try { W.fetch = _fetch; } catch (e) {}
      try { W.Audio = _Audio; } catch (e) {}
      try {
        var sel = '.dshwv-root,.dshwv-menu,.dshwv-menu-btn,.dshwv-bubble';
        var els = document.querySelectorAll(sel);
        for (var i = 0; i < els.length; i++) if (els[i].parentNode) els[i].parentNode.removeChild(els[i]);
      } catch (e) {}
      try { delete W.__dshWhaleWidget; } catch (e) {}
      try { delete W.__dshWhaleInit; } catch (e) {}
      ctx.log('[whale-dsh] cleaned');
    };
  },
  onUnload: function () { if (typeof this._cleanup === 'function') this._cleanup(); }
};
